"""Report content, part E: Question 6."""
import math

from content_a import load, g, e, f


def section6_a(R):
    B = []
    psf = R["q6_1_psf"]
    B.append(("h1", "Question 6 - Motion blur and deblurring"))
    B.append(("h2", "6.1 Model and synthesis"))
    B.append(("p", "**Continuous PSF.** Uniform linear motion of length $L$ along direction $\\theta$ during the exposure moves a point of the scene along the segment $t(\\cos\\theta,\\sin\\theta)$, $t\\in[-L/2,L/2]$, with constant speed, so the energy of a point is spread uniformly along the segment:"))
    B.append(("eq", r"h(x,y)=\frac1L\int_{-L/2}^{L/2}\delta(x-t\cos\theta,\;y-t\sin\theta)\,dt,\qquad \iint h\,dx\,dy=\frac1L\int_{-L/2}^{L/2}dt=1"))
    B.append(("p", "(a one-dimensional line mass of density $1/L$ per unit length; $x$ is the column direction, $y$ the row direction pointing down, and $\\theta$ is measured from $+x$ towards $+y$)."))
    B.append(("p", "**Discretisation and normalisation.** The segment is sampled by the midpoint rule at $n=\\lceil32L\\rceil$ points $t_j=(j+\\tfrac12)L/n-L/2$ (each carrying mass $1/n$), and each point is *splatted* with bilinear weights onto the four nearest pixels of a grid with periodic indexing, the origin being pixel $(0,0)$. The result is non-negative, compactly supported (%d non-zero pixels for $L=25$, $\\theta=30^\\circ$) and sums to exactly %s by construction (also checked in tests). **Boundary convention (forward and inverse alike): circular**; blurring is $g=\\mathcal F^{-1}\\{H\\,\\mathcal F\\{f\\}\\}$ with $H=\\mathrm{DFT}\\{\\text{psf}\\}$ on the full image grid and deconvolution divides by the same $H$, so the model used to construct $H$ and the model used to blur are identical (no cropping of boundary pixels is needed). For the real photographs (Section 6.4) the image is mirror-padded before the circular deconvolution to avoid wraparound." % (psf["support_pixels"], f(psf["sum"], 1))))
    B.append(("p", "**Noise and SNR.** The blurred image (in [0,1]) is corrupted by zero-mean white Gaussian noise at a stated SNR, defined as"))
    B.append(("eq", r"\mathrm{SNR}_{dB}=10\log_{10}\frac{\sum_{x,y,c}f(x,y,c)^{2}}{\sum_{x,y,c}n(x,y,c)^{2}},\qquad \sigma_n^{2}=\frac{\sum f^{2}}{N_{px}\,10^{\mathrm{SNR}_{dB}/10}}"))
    B.append(("p", "with $f$ the *clean* image on the [0,1] scale (not mean-removed). The noise is not clipped. Experiments use the 1536x1024 working version of the instructor-provided reference photograph (Section 5.1; SNR = 20, 30, 40, 50 dB give $\\sigma_n=$ %s on the [0,1] scale)." % ", ".join(f(R["q6_3_levels"][k]["sigma_noise_(0..1)"], 4) for k in ("20", "30", "40", "50"))))
    B.append(("p", "**Motion OTF.** Fourier transforming the PSF with $e^{-2\\pi i(f_xx+f_yy)}$ (frequencies in cycles/pixel) and using the sifting property,"))
    B.append(("eq", r"H(f_x,f_y)=\frac1L\int_{-L/2}^{L/2}e^{-2\pi i\,t\,s}\,dt=\frac{\sin(\pi L s)}{\pi L s}=\mathrm{sinc}(L s),\qquad s=f_x\cos\theta+f_y\sin\theta"))
    B.append(("p", "with $\\mathrm{sinc}(z)=\\sin(\\pi z)/(\\pi z)$. Zeros occur at $\\pi Ls=m\\pi$:"))
    B.append(("eq", r"f_x\cos\theta+f_y\sin\theta=\frac{m}{L},\qquad m\in\mathbb Z\setminus\{0\}"))
    B.append(("p", "**Adjacent zeros are spaced $1/L$** in the projected frequency $s$, and each zero set is a *straight line* in the $(f_x,f_y)$ plane with normal vector $(\\cos\\theta,\\sin\\theta)$, i.e. **the zero lines are perpendicular to the motion direction**; $H$ depends on frequency only through its projection on the motion direction, so it is constant along every line perpendicular to the motion, and the dark stripes of $|H|$ are those lines. A discrete FFT grid may sample near, rather than at, the theoretical zeros (the lines do not pass through grid points for general $\\theta$)."))
    B.append(("p", "**Numerical check of the discretisation.** For the experiment ($L=25$, $\\theta=30^\\circ$, 1536x1024 grid): $H$ is real to %s (point-symmetric PSF), $H(0,0)=%s$, and along the motion direction the samples of $|H|$ have their minima at $m/L$ within %s cycles/pixel (largest deviation over the 11 zeros up to 0.45 cycles/pixel; the grid spacing is 1/1536 = 6.5e-4). The DFT of the splatted PSF is *not* exactly the continuous sinc: bilinear splatting convolves the line with the triangle kernel, whose transfer function is $\\mathrm{sinc}^2(f_x)\\mathrm{sinc}^2(f_y)$, and sampling aliases the product. The relation $H_{DFT}=\\sum_{k_x,k_y}\\mathrm{sinc}(Ls(f-k))\\,\\mathrm{sinc}^2(f_x-k_x)\\,\\mathrm{sinc}^2(f_y-k_y)$ holds to %s over the whole grid (4 aliases each side), and the $k=0$ term alone is accurate to %s for $|f|<0.1$. The extra smooth factor does not move the zero lines. Axis-aligned check: for $L=8$, $\\theta=0$ on a 64-point grid $|H|=%s$ at $f=m/8$ (m=1,2,3): exact Dirichlet zeros." % (e(psf["max_|imag(H)|"]), f(psf["H_dc"], 1), e(max(abs(x) for x in psf["ray_zero_position_error_(cycles/pixel)"])), e(psf["max|H-aliased_sum(sinc*triangle)|_(+-4_aliases)"]), e(psf["max|H-Ha*interp|_(k=0_term_only)_|f|<0.1"]), ", ".join(e(x, 0) for x in psf["axis_aligned_L=8_theta=0_|H|_at_f=m/8_(m=1,2,3)"]))))
    ng = R["q6_2_noise_gain"]
    lv = R["q6_3_levels"]
    B.append(("h2", "6.2 Naive inverse filtering and why it fails"))
    B.append(("p", "The naive inverse is $\\hat F=G/H$ with $G=HF+N$, i.e. $\\hat F=F+N/H$. A numerical floor is needed because $H$ has samples at (numerically) zero: $|H|$ is replaced by $\\max(|H|,10^{-8})$ keeping its sign (the floor $10^{-8}$ only avoids division by exact zero; a practical floor of $10^{-3}$ is also reported). On the 1536x1024 grid the smallest $|H|$ is %s, %.1f%% of the frequency samples have $|H|<10^{-2}$ and %.2f%% have $|H|<10^{-3}$. The noise variance gain $\\mathrm{mean}(1/|H|^2)$ is %s with floor $10^{-8}$ and %s with floor $10^{-3}$ (against %s for the Wiener filter with $K=10^{-3}$, Section 6.3)." % (e(ng["min|H|_over_grid"]), 100 * ng["frac_|H|<1e-2"], 100 * ng["frac_|H|<1e-3"], e(ng["variance_gain_mean(1/|H|^2)_floor1e-8"]), e(ng["variance_gain_mean(1/|H|^2)_floor1e-3"]), e(ng["variance_gain_mean(1/|H|^2)_K=1e-3"]))))
    B.append(("fig", "figures/q6_spectra.png", "Left: log10|G| of the blurred and noisy (30 dB) luminance. Middle: log10|G/H|, the raw (unclipped) inverse estimate: the noise is amplified into bright bands exactly on the zero lines of H. Right: log10|F| of the clean image. Cyan: the predicted zero lines m/L (L = 25, theta = 30 deg, |m| <= 17); white dots: the sampled frequencies nearest to the lines m = +-1, +-2, +-3.", 1.0))
    rows = [[k, f(lv[k]["achieved_SNR_dB"], 3), f(lv[k]["noisy_blurred_PSNR"], 2), f(lv[k]["naive_inverse_floor1e-8_PSNR"], 2), f(lv[k]["naive_inverse_floor1e-3_PSNR"], 2), g(lv[k]["naive_inverse_rms_error_(0..1,_unclipped)"], 4)] for k in ("20", "30", "40", "50")]
    B.append(("table", "Table 6.1. Naive inverse filtering of the blurred+noisy reference image (L=25, theta=30). PSNR (dB, vs the clean image, output clipped for the metric) of the blurred+noisy input and of the inverse estimate with floors 1e-8 and 1e-3; RMS error of the *unclipped* inverse estimate on the [0,1] scale.", ["SNR (dB)", "achieved SNR", "PSNR blurred+noisy", "PSNR naive inverse (floor 1e-8)", "PSNR naive inverse (floor 1e-3)", "RMS error of unclipped inverse"], rows, "rrrrrr"))
    B.append(("p", "**Noise amplification and the zero spacing.** At a frequency where $|H|$ is tiny the term $N/H$ is huge: the amplified-noise bands in Figure 6.1 (middle) are exactly the lines $f_x\\cos\\theta+f_y\\sin\\theta=m/L$, repeated with the spacing $1/L=0.04$ cycles/pixel, so a 1536x1024 spectrum is crossed by dozens of such lines and the noise is amplified without bound on each of them. Between the zeros $|H|$ is a sinc side lobe of height $\\lesssim1/(\\pi L|s|)\\approx1/(78|s|)$, so even in the 'pass bands' the inverse multiplies the noise by $1/|H|$, which is large at all but the lowest frequencies. The inverse estimate has an RMS error of %s (SNR 20 dB) down to %s (50 dB) on a [0,1] image and PSNR %.1f-%.1f dB, *worse than the blurred input* (%.1f-%.1f dB) at all four noise levels." % (g(lv["20"]["naive_inverse_rms_error_(0..1,_unclipped)"], 4), g(lv["50"]["naive_inverse_rms_error_(0..1,_unclipped)"], 3), min(lv[k]["naive_inverse_floor1e-8_PSNR"] for k in lv), max(lv[k]["naive_inverse_floor1e-8_PSNR"] for k in lv), min(lv[k]["noisy_blurred_PSNR"] for k in lv), max(lv[k]["noisy_blurred_PSNR"] for k in lv))))
    B.append(("p", "**In one sentence:** because the inverse filter multiplies the noise spectrum by $1/H$, any nonzero noise component $N(u,v)$ at a frequency where $|H(u,v)|\\to0$ is amplified by the unbounded factor $1/|H(u,v)|$, while the signal $F(u,v)H(u,v)$ there vanishes."))
    B.append(("h2", "6.3 Wiener deconvolution"))
    B.append(("p", "**Derivation.** For $G=HF+N$ with $F$, $N$ uncorrelated with PSDs $S_{ff}$, $S_{nn}$, the linear estimate $\\hat F=WG$ minimising $E|F-WG|^2$ at each frequency satisfies the orthogonality condition $E[(F-WG)\\bar G]=0$, i.e. $S_{ff}\\bar H=W(|H|^2S_{ff}+S_{nn})$, hence"))
    B.append(("eq", r"W(u,v)=\frac{\overline{H}\,S_{ff}}{|H|^{2}S_{ff}+S_{nn}}=\frac{\overline{H}}{|H|^{2}+K},\qquad \hat F=\frac{\overline H\,G}{|H|^{2}+K},\quad K=\frac{S_{nn}}{S_{ff}}"))
    B.append(("p", "**Scaling and interpretation of K.** Images are in [0,1] and $H$ has $H(0)=1$; with white noise of variance $\\sigma_n^2$ and a signal modelled as a flat spectrum with the *average* signal power $\\overline{f^2}=\\sum f^2/N_{px}$ (the quantity in the SNR definition), $K=\\sigma_n^2/\\overline{f^2}=10^{-\\mathrm{SNR}_{dB}/10}$: **$K$ is a constant noise-to-signal power ratio**. For $K\\to0$ the filter becomes the inverse $1/H$ (unstable at the zeros); for $|H|^2\\ll K$ it becomes $\\bar H/K\\to0$ (those frequencies are suppressed rather than amplified); for $K\\to\\infty$ it tends to $\\bar H G/K$, i.e. the blurred image blurred *again* by $\\bar H$ (under-deconvolution)."))
    B.append(("p", "**Sweep.** $K=10^{-8}\\ldots10^{0}$ in steps of 0.05 decades (161 values) at each of four noise levels; PSNR is computed against the clean reference for every $K$ (the same noise realisation for all $K$ at a given level). **Failure modes:** at $K=10^{-8}$ (inverse-like) the PSNR is %s dB for SNR = 20, 30, 40, 50 dB - far below that of the blurred image, because of the amplified noise bands; at $K=1$ the result is under-deconvolved (still blurred, and additionally blurred by $\\bar H$) with PSNR %s dB at every noise level (essentially independent of the noise, since the filter has become $\\approx\\bar H$). The optimum lies between (Figure 6.2, Table 6.2)." % (", ".join(f(lv[k]["PSNR_at_K=1e-8_(inverse-like)"], 1) for k in ("20", "30", "40", "50")), ", ".join(f(lv[k]["PSNR_at_K=1_(under-deconvolved)"], 1) for k in ("20", "30", "40", "50")))))
    B.append(("fig", "figures/q6_ksweep.png", "Left: PSNR vs K for four noise levels (black dots: optimum K; dotted vertical lines: the textbook value K = 10^(-SNR/10)). Right: measured optimum K against 10^(-SNR/10).", 1.0))
    rows = [[k, g(lv[k]["K_theory_=10^(-SNR/10)"], 3), g(lv[k]["K_opt"], 3), f(lv[k]["Kopt/Ktheory"], 1), f(lv[k]["PSNR_at_Kopt"], 2), f(lv[k]["SSIM_at_Kopt"], 3), f(lv[k]["PSNR_at_Ktheory"], 2), f(lv[k]["noisy_blurred_PSNR"], 2)] for k in ("20", "30", "40", "50")]
    B.append(("table", "Table 6.2. K that maximises PSNR against the clean reference at each noise level (oracle: the clean image is used to read the optimum), compared with the mean-power NSR 10^(-SNR/10); PSNR/SSIM at the optimum, PSNR at K = 10^(-SNR/10) and of the blurred+noisy input.", ["SNR (dB)", "K = 10^(-SNR/10)", "K_opt (max PSNR)", "K_opt / K_theory", "PSNR at K_opt", "SSIM at K_opt", "PSNR at K_theory", "PSNR blurred+noisy"], rows, "rrrrrrrr"))
    B.append(("p", "**How the optimum changes with noise level.** $K_{opt}$ decreases monotonically as the noise decreases: %s for SNR = 20, 30, 40, 50 dB, a factor of %.0f over a 1000-fold (30 dB) change in noise power, i.e. $K_{opt}\\propto\\mathrm{NSR}^{%.2f}$ (log-log slope), not proportional to the noise power. It is also larger than the mean-power ratio by a factor of %s to %s, growing as the noise falls. The reason is that $K=S_{nn}/S_{ff}$ assumed one constant $S_{ff}$, whereas natural images have a spectrum falling like $1/f^{\\alpha}$: the frequencies where the inverse filter is dangerous (the zeros and the side lobes at higher $|s|$) are mid/high frequencies where $S_{ff}$ is *orders of magnitude below its mean*, so the effective local NSR there is far larger than the global ratio, and the best single constant is a compromise weighted towards them. The gain at the optimum over the blurred+noisy input is %.1f, %.1f, %.1f, %.1f dB; at $K=K_{theory}$ the result is still dominated by noise bands (PSNR %.1f dB at 30 dB SNR vs %.1f dB at $K_{opt}$)." % (", ".join(g(lv[k]["K_opt"], 3) for k in ("20", "30", "40", "50")), lv["20"]["K_opt"] / lv["50"]["K_opt"], math.log10(lv["20"]["K_opt"] / lv["50"]["K_opt"]) / 3.0, f(lv["20"]["Kopt/Ktheory"], 1), f(lv["50"]["Kopt/Ktheory"], 0), *[lv[k]["PSNR_at_Kopt"] - lv[k]["noisy_blurred_PSNR"] for k in ("20", "30", "40", "50")], lv["30"]["PSNR_at_Ktheory"], lv["30"]["PSNR_at_Kopt"])))
    B.append(("fig", "figures/q6_deconv_grid.png", "Deconvolution at 30 dB SNR (200x300 crop): clean, blurred+noise, naive inverse, Wiener with K = 1e-6 (noise amplification, stripes), K_opt = 0.025, K = 0.1 (residual blur), and the full-frame optimum.", 1.0))
    return B
